# ═══════════════════════════════════════════════════════════════
# FONCTION DE TRADUCTION
# ═══════════════════════════════════════════════════════════════

def T(k):
    """
    Traduit une clé selon la langue active.

    Priorité de résolution :
    1. La langue active (st.session_state.cfg_lang)
    2. L'anglais (fallback)
    3. Le français (fallback)
    4. La clé elle-même (dernier recours)

    Args:
        k: Clé de traduction (ex: "home", "login")

    Returns:
        La traduction dans la langue active, ou la clé si introuvable.
    """
    lang = st.session_state.get("cfg_lang", "fr")
    return (
        I18N.get(lang, {}).get(k)
        or I18N["en"].get(k)
        or I18N["fr"].get(k)
        or k
    )